import{_ as i,o as s,c as t,a2 as r}from"./chunks/framework.DpXDHk3d.js";const d=JSON.parse('{"title":"15.4 高频100道原题-选择题","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/15-chapter-15-li-lun-kao-shi-ying-shi-ji-qiao/15-4-gao-pin-100-dao-yuan-ti-xuan-ze-ti.md","filePath":"electrician/low-voltage-electrician/15-chapter-15-li-lun-kao-shi-ying-shi-ji-qiao/15-4-gao-pin-100-dao-yuan-ti-xuan-ze-ti.md","lastUpdated":1795661954000}'),o={name:"electrician/low-voltage-electrician/15-chapter-15-li-lun-kao-shi-ying-shi-ji-qiao/15-4-gao-pin-100-dao-yuan-ti-xuan-ze-ti.md"};function n(p,l,g,a,u,m){return s(),t("div",null,[...l[0]||(l[0]=[r('<h1 id="_15-4-高频100道原题-选择题" tabindex="-1">15.4 高频100道原题-选择题 <a class="header-anchor" href="#_15-4-高频100道原题-选择题" aria-label="Permalink to &quot;15.4 高频100道原题-选择题&quot;">​</a></h1><blockquote><p><strong>说明</strong>:以下 100 道题按低压电工理论机考的高频考点整理,题型、问法和选项设置贴近真实机考,但不是官方真题扫描件。建议先独立作答,再展开每道题下方的&quot;答案与解析&quot;核对。题目按&quot;法规 → 基础 → 安全 → 仪表电器 → 线路电机 → 配电照明 → 防火急救&quot;的顺序排列。</p></blockquote><p><strong>使用方法</strong>:每道题控制在 40 秒以内;做错的题记下题号,回到 <a href="/some-docs/electrician/low-voltage-electrician/15-chapter-15-li-lun-kao-shi-ying-shi-ji-qiao/15-3-gao-pin-yi-cuo-kao-dian-zong-jie.html">15.3 高频易错考点总结</a>对应的模块补一遍。</p><h2 id="一、安全生产法律法规-第-1-15-题" tabindex="-1">一、安全生产法律法规(第 1~15 题) <a class="header-anchor" href="#一、安全生产法律法规-第-1-15-题" aria-label="Permalink to &quot;一、安全生产法律法规(第 1~15 题)&quot;">​</a></h2><p><strong>1.</strong> 低压电工作业是指对( )kV 以下电气设备进行的安装、检修、运行、维护作业。</p><ul><li>A. 1</li><li>B. 10</li><li>C. 35</li><li>D. 0.4</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:高压与低压以 <strong>1kV(1000V)</strong> 为分界,1kV 以下(不含 1kV)属于低压。0.4kV 虽然也是低压,但它不是分界值;10kV、35kV 都属于高压。</p></details><p><strong>2.</strong> 特种作业操作证的有效期为( )年。</p><ul><li>A. 2</li><li>B. 3</li><li>C. 6</li><li>D. 10</li></ul><details><summary>答案与解析</summary><p><strong>答案:C</strong></p><p>解析:现行规定特种作业操作证有效期 <strong>6 年</strong>。容易混淆的是&quot;3 年&quot;,那是<strong>复审周期</strong>,不是有效期。</p></details><p><strong>3.</strong> 特种作业操作证每( )年复审一次。</p><ul><li>A. 1</li><li>B. 2</li><li>C. 3</li><li>D. 6</li></ul><details><summary>答案与解析</summary><p><strong>答案:C</strong></p><p>解析:证书 6 年有效,每 <strong>3 年</strong>复审一次,6 年内要复审两次。记法:&quot;六证三审&quot;。</p></details><p><strong>4.</strong> 申请特种作业操作证的人员,年龄应年满( )周岁。</p><ul><li>A. 16</li><li>B. 18</li><li>C. 20</li><li>D. 22</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:特种作业属于高危作业,要求年满 <strong>18 周岁</strong>,且不超过国家法定退休年龄。16 周岁是未成年人,不能从事特种作业。</p></details><p><strong>5.</strong> 特种作业人员一般应具备( )及以上文化程度。</p><ul><li>A. 小学</li><li>B. 初中</li><li>C. 高中</li><li>D. 大专</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:规定要求具备<strong>初中及以上</strong>文化程度,以保证能够理解安全技术知识和操作规程。</p></details><p><strong>6.</strong> 特种作业操作证由( )考核发证。</p><ul><li>A. 人力资源和社会保障部门</li><li>B. 应急管理部门</li><li>C. 市场监督管理部门</li><li>D. 行业协会</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:特种作业操作证由<strong>应急管理部门</strong>(原安全生产监督管理部门)考核发证。人社部门发的是职业资格证书,两者不是一回事。</p></details><p><strong>7.</strong> 从业人员发现直接危及人身安全的紧急情况时,有权( )。</p><ul><li>A. 继续作业</li><li>B. 停止作业或采取可能的应急措施后撤离作业场所</li><li>C. 等待领导指令</li><li>D. 先完成手头工作</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:《安全生产法》赋予从业人员紧急避险权:发现直接危及人身安全的紧急情况时,有权停止作业或在采取可能的应急措施后撤离,且不得因此降低其工资福利待遇。</p></details><p><strong>8.</strong> 从业人员有权拒绝( )和强令冒险作业。</p><ul><li>A. 违章指挥</li><li>B. 加班安排</li><li>C. 岗位调整</li><li>D. 安全培训</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:从业人员的拒绝权针对的是<strong>违章指挥</strong>和强令冒险作业,这是法律赋予的权利,不是对抗管理的借口。</p></details><p><strong>9.</strong> 下列不属于特种作业的是( )。</p><ul><li>A. 低压电工作业</li><li>B. 焊接与热切割作业</li><li>C. 高处作业</li><li>D. 办公室文秘</li></ul><details><summary>答案与解析</summary><p><strong>答案:D</strong></p><p>解析:特种作业是指容易发生事故、对操作者本人及他人和周围设施的安全有重大危害的作业。电工作业、焊接与热切割、高处作业等都属于特种作业;文秘工作不属于。</p></details><p><strong>10.</strong> 特种作业操作证复审前,持证人应当参加必要的( )并考试合格。</p><ul><li>A. 安全培训</li><li>B. 技能竞赛</li><li>C. 学历教育</li><li>D. 体能测试</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:复审不是&quot;交钱盖章&quot;,而是要通过必要的<strong>安全培训</strong>并考试合格,确认持证人的安全知识和技能仍然有效。</p></details><p><strong>11.</strong> 特种作业操作证遗失后,正确的处理方式是( )。</p><ul><li>A. 使用复印件上岗</li><li>B. 向发证机关申请补发</li><li>C. 借用他人证件</li><li>D. 自行打印一份</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:证件遗失应向<strong>发证机关申请补发</strong>。使用复印件、借用他人证件都属于无证上岗,是违法行为。</p></details><p><strong>12.</strong> 生产经营单位的主要负责人对本单位安全生产工作( )。</p><ul><li>A. 全面负责</li><li>B. 部分负责</li><li>C. 不负责</li><li>D. 仅负技术责任</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:《安全生产法》规定,生产经营单位的主要负责人对本单位的安全生产工作<strong>全面负责</strong>,这是法定职责。</p></details><p><strong>13.</strong> 未经安全生产教育和培训合格的从业人员,( )。</p><ul><li>A. 可以上岗</li><li>B. 不得上岗作业</li><li>C. 可边干边学</li><li>D. 经班组长同意可上岗</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:未经安全生产教育和培训合格的从业人员<strong>不得上岗作业</strong>,这是强制性规定,不能以&quot;边干边学&quot;或口头同意代替。</p></details><p><strong>14.</strong> 电工在作业中应当坚持的方针是( )。</p><ul><li>A. 效率第一</li><li>B. 安全第一、预防为主</li><li>C. 先作业后报告</li><li>D. 经验优先</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:安全生产的基本方针是&quot;<strong>安全第一、预防为主、综合治理</strong>&quot;。选项中只有 B 完整对应。</p></details><p><strong>15.</strong> 从事特种作业的人员,必须取得( )后方可上岗作业。</p><ul><li>A. 职业资格证书</li><li>B. 特种作业操作证</li><li>C. 学历证书</li><li>D. 健康证</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:特种作业实行持证上岗制度,必须取得<strong>特种作业操作证</strong>。职业资格证、学历证、健康证都不能替代。</p></details><h2 id="二、电工基础知识-第-16-30-题" tabindex="-1">二、电工基础知识(第 16~30 题) <a class="header-anchor" href="#二、电工基础知识-第-16-30-题" aria-label="Permalink to &quot;二、电工基础知识(第 16~30 题)&quot;">​</a></h2><p><strong>16.</strong> 电路中形成持续电流的必要条件是( )。</p><ul><li>A. 有电压且电路闭合</li><li>B. 只有电压</li><li>C. 只有电阻</li><li>D. 只有电源</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:有电压是外因,电路闭合是内因,两者缺一不可。只有电压而电路断开,不会形成持续电流。</p></details><p><strong>17.</strong> 电阻的单位是( )。</p><ul><li>A. 伏特</li><li>B. 安培</li><li>C. 欧姆</li><li>D. 瓦特</li></ul><details><summary>答案与解析</summary><p><strong>答案:C</strong></p><p>解析:电阻的单位是<strong>欧姆(Ω)</strong>;伏特是电压单位,安培是电流单位,瓦特是功率单位。</p></details><p><strong>18.</strong> 欧姆定律的表达式是( )。</p><ul><li>A. I=U/R</li><li>B. U=IR²</li><li>C. R=UI</li><li>D. P=UI</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:欧姆定律为 <strong>I=U/R</strong>,即电流与电压成正比、与电阻成反比。D 是电功率公式,不是欧姆定律。</p></details><p><strong>19.</strong> 两个 10Ω 的电阻串联,总电阻为( )Ω。</p><ul><li>A. 5</li><li>B. 10</li><li>C. 20</li><li>D. 100</li></ul><details><summary>答案与解析</summary><p><strong>答案:C</strong></p><p>解析:串联电阻相加,R=R1+R2=10+10=<strong>20Ω</strong>。5Ω 是并联的结果。</p></details><p><strong>20.</strong> 两个 10Ω 的电阻并联,总电阻为( )Ω。</p><ul><li>A. 5</li><li>B. 10</li><li>C. 20</li><li>D. 100</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:两个相同电阻并联,总电阻为单个的一半:10/2=<strong>5Ω</strong>。并联总电阻一定小于任一分电阻。</p></details><p><strong>21.</strong> 串联电路中,各处的( )相等。</p><ul><li>A. 电压</li><li>B. 电流</li><li>C. 电阻</li><li>D. 功率</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:串联电路只有一条通路,所以<strong>电流处处相等</strong>;电压则按电阻比例分配。</p></details><p><strong>22.</strong> 并联电路中,各支路两端的( )相等。</p><ul><li>A. 电流</li><li>B. 电压</li><li>C. 电阻</li><li>D. 电能</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:并联各支路接在同一对节点上,所以<strong>两端电压相等</strong>;电流按各支路电阻反比分配。</p></details><p><strong>23.</strong> 我国工频交流电的频率是( )Hz。</p><ul><li>A. 50</li><li>B. 60</li><li>C. 100</li><li>D. 314</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:我国工频为 <strong>50Hz</strong>,周期 0.02s。60Hz 是部分国家的标准;314 是角频率(2πf)的近似值,不是频率。</p></details><p><strong>24.</strong> 频率为 50Hz 的交流电,其周期为( )s。</p><ul><li>A. 0.01</li><li>B. 0.02</li><li>C. 0.05</li><li>D. 0.1</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:周期 T=1/f=1/50=<strong>0.02s</strong>。记法:&quot;五十赫兹,零点零二秒&quot;。</p></details><p><strong>25.</strong> 三相四线制中,线电压为 380V,则相电压为( )V。</p><ul><li>A. 110</li><li>B. 220</li><li>C. 380</li><li>D. 660</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:星形连接时线电压是相电压的 √3 倍,u相=380/√3≈<strong>220V</strong>。这就是我们常说的&quot;三相 380V、单相 220V&quot;。</p></details><p><strong>26.</strong> 三相电源星形连接时,线电压是相电压的( )倍。</p><ul><li>A. 1</li><li>B. √2</li><li>C. √3</li><li>D. 2</li></ul><details><summary>答案与解析</summary><p><strong>答案:C</strong></p><p>解析:星形连接 <strong>u线=√3·u相</strong>;三角形连接时线电压等于相电压。√2 是交流电最大值与有效值的比值,不要混。</p></details><p><strong>27.</strong> 下列电功率计算公式中,正确的是( )。</p><ul><li>A. P=UI</li><li>B. P=I²R</li><li>C. P=U²/R</li><li>D. 以上都正确</li></ul><details><summary>答案与解析</summary><p><strong>答案:D</strong></p><p>解析:在纯电阻电路中,由欧姆定律可推出 <strong>P=UI=I²R=U²/R</strong>,三式等价,所以都对。</p></details><p><strong>28.</strong> 1kW·h 的电能等于( )度电。</p><ul><li>A. 0.1</li><li>B. 1</li><li>C. 10</li><li>D. 1000</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:1 度电就是 1kW·h,即功率 1kW 的电器工作 1 小时消耗的电能。1000 是 1kW·h 换算成 W·h 的数值(1000W·h),不是&quot;度&quot;的数值。</p></details><p><strong>29.</strong> 电流通过电阻时,电能主要转化为( )。</p><ul><li>A. 磁场能</li><li>B. 热能</li><li>C. 化学能</li><li>D. 机械能</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:电阻对电流有阻碍作用,电能主要转化为<strong>热能</strong>,这就是电流的热效应,也是导线发热、电气火灾的根源。</p></details><p><strong>30.</strong> 在纯电感电路中,电流与电压的相位关系是( )。</p><ul><li>A. 同相</li><li>B. 电流超前电压 90°</li><li>C. 电流滞后电压 90°</li><li>D. 相差 180°</li></ul><details><summary>答案与解析</summary><p><strong>答案:C</strong></p><p>解析:纯电感电路中<strong>电流滞后电压 90°</strong>;纯电容电路则相反,电流超前电压 90°。记法:&quot;电感滞后,电容超前&quot;。</p></details><h2 id="三、电气安全技术-第-31-45-题" tabindex="-1">三、电气安全技术(第 31~45 题) <a class="header-anchor" href="#三、电气安全技术-第-31-45-题" aria-label="Permalink to &quot;三、电气安全技术(第 31~45 题)&quot;">​</a></h2><p><strong>31.</strong> 下列不属于我国安全电压额定值的是( )。</p><ul><li>A. 42V</li><li>B. 36V</li><li>C. 24V</li><li>D. 220V</li></ul><details><summary>答案与解析</summary><p><strong>答案:D</strong></p><p>解析:我国安全电压额定值系列为 <strong>42/36/24/12/6V</strong>。220V 是相电压,属于危险电压,不是安全电压。</p></details><p><strong>32.</strong> 一般情况下,我国常用的安全电压是( )V。</p><ul><li>A. 12</li><li>B. 24</li><li>C. 36</li><li>D. 42</li></ul><details><summary>答案与解析</summary><p><strong>答案:C</strong></p><p>解析:42V 是安全电压系列的最高值,实际一般场所最常用的是 <strong>36V</strong>;潮湿、金属容器等特殊场所还要降到 24V 或 12V。</p></details><p><strong>33.</strong> 在特别潮湿场所或金属容器内使用行灯,其电压不应超过( )V。</p><ul><li>A. 36</li><li>B. 24</li><li>C. 12</li><li>D. 6</li></ul><details><summary>答案与解析</summary><p><strong>答案:C</strong></p><p>解析:一般场所行灯 ≤36V;特别潮湿场所、金属容器内人体电阻显著下降,行灯电压不得超过 <strong>12V</strong>。</p></details><p><strong>34.</strong> 人体工频感知电流约为( )mA。</p><ul><li>A. 1</li><li>B. 10</li><li>C. 50</li><li>D. 100</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:感知电流是人刚能感觉到的最小电流,工频约为 <strong>1mA</strong>。10mA 是摆脱电流,50mA 是危险电流。</p></details><p><strong>35.</strong> 人体工频摆脱电流约为( )mA。</p><ul><li>A. 1</li><li>B. 10</li><li>C. 30</li><li>D. 50</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:摆脱电流是人触电后能自主摆脱带电体的最大电流,工频约为 <strong>10mA</strong>。超过这个值,肌肉痉挛就无法自行摆脱。</p></details><p><strong>36.</strong> 一般认为,通过人体的工频电流达到( )mA 以上时会有生命危险。</p><ul><li>A. 1</li><li>B. 10</li><li>C. 30</li><li>D. 50</li></ul><details><summary>答案与解析</summary><p><strong>答案:D</strong></p><p>解析:工频 <strong>50mA</strong> 以上可能引起心室颤动,危及生命。漏电保护器取 30mA 动作,就是为了在达到危险值前切断电源。</p></details><p><strong>37.</strong> 保护接地的接地电阻一般不应大于( )Ω。</p><ul><li>A. 1</li><li>B. 4</li><li>C. 10</li><li>D. 30</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:保护接地电阻一般要求 <strong>≤4Ω</strong>;重复接地可放宽到 ≤10Ω。记法:&quot;接地四,重复十&quot;。</p></details><p><strong>38.</strong> 重复接地的接地电阻一般不应大于( )Ω。</p><ul><li>A. 4</li><li>B. 10</li><li>C. 30</li><li>D. 100</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:重复接地是保护接零的补充措施,接地电阻一般要求 <strong>≤10Ω</strong>,比保护接地的 4Ω 略宽。</p></details><p><strong>39.</strong> 一般场所漏电保护器的额定漏电动作电流和动作时间分别为( )。</p><ul><li>A. 30mA、0.1s</li><li>B. 100mA、0.3s</li><li>C. 300mA、0.5s</li><li>D. 10mA、1s</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:一般场所人身保护用漏电保护器为 <strong>30mA、≤0.1s</strong>。100mA 以上多用于防火或分级保护,不是人身保护的首选。</p></details><p><strong>40.</strong> 保护接零适用于( )系统。</p><ul><li>A. IT</li><li>B. TT</li><li>C. TN</li><li>D. 任意系统</li></ul><details><summary>答案与解析</summary><p><strong>答案:C</strong></p><p>解析:保护接零要求电源中性点直接接地并引出中性线,即 <strong>TN 系统</strong>(TN-S、TN-C、TN-C-S)。IT、TT 系统采用保护接地。</p></details><p><strong>41.</strong> 同一台变压器供电的低压系统中,保护接地与保护接零( )。</p><ul><li>A. 可以混用</li><li>B. 不得混用</li><li>C. 可部分混用</li><li>D. 视负载而定</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:同一系统内混用,一旦接零设备发生碰壳,故障电流会通过接地设备的外壳和大地形成回路,使所有接地设备外壳带上危险电压,所以<strong>严禁混用</strong>。</p></details><p><strong>42.</strong> 低压电气设备的绝缘电阻一般不应低于( )MΩ。</p><ul><li>A. 0.1</li><li>B. 0.5</li><li>C. 1</li><li>D. 2</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:低压线路和设备的绝缘电阻一般要求 <strong>≥0.5MΩ</strong>。手持电动工具要求更高(I 类 ≥2MΩ,II 类 ≥7MΩ)。</p></details><p><strong>43.</strong> 安全电压的电源应采用( )。</p><ul><li>A. 自耦调压器</li><li>B. 安全隔离变压器</li><li>C. 普通变压器</li><li>D. 变频器</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:安全电压必须由<strong>安全隔离变压器</strong>供电。自耦调压器和普通变压器一、二次侧不隔离,一次侧故障电压可能窜入二次侧,起不到保护作用。</p></details><p><strong>44.</strong> 电流通过人体时,最危险的路径是经过( )。</p><ul><li>A. 四肢</li><li>B. 心脏</li><li>C. 皮肤表面</li><li>D. 肌肉</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:电流通过<strong>心脏</strong>时最易引起心室颤动,危险性最大。左手到右脚、手到手等经过心脏的路径都属于危险路径。</p></details><p><strong>45.</strong> 触电方式中,最常见的是( )。</p><ul><li>A. 单相触电</li><li>B. 两相触电</li><li>C. 跨步电压触电</li><li>D. 感应电压触电</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:<strong>单相触电</strong>是人体接触一相带电体,占触电事故的绝大多数。两相触电虽然更危险,但发生概率较低。</p></details><h2 id="四、电工仪表与低压电器-第-46-58-题" tabindex="-1">四、电工仪表与低压电器(第 46~58 题) <a class="header-anchor" href="#四、电工仪表与低压电器-第-46-58-题" aria-label="Permalink to &quot;四、电工仪表与低压电器(第 46~58 题)&quot;">​</a></h2><p><strong>46.</strong> 测量电压时,电压表应与被测电路( )。</p><ul><li>A. 串联</li><li>B. 并联</li><li>C. 混联</li><li>D. 断开</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:电压表内阻很大,应<strong>并联</strong>在被测电路两端。若串联,会因内阻大而几乎切断电路,读数也不准。记法:&quot;压并流串&quot;。</p></details><p><strong>47.</strong> 测量电流时,电流表应与被测电路( )。</p><ul><li>A. 串联</li><li>B. 并联</li><li>C. 混联</li><li>D. 短接</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:电流表内阻很小,必须<strong>串联</strong>接入被测电路。若并联,相当于把电源短路,会烧坏仪表甚至引发事故。</p></details><p><strong>48.</strong> 使用万用表测量电阻前,必须( )。</p><ul><li>A. 给电路通电</li><li>B. 切断被测电路电源</li><li>C. 把量程调到最大</li><li>D. 短接表笔</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:测量电阻必须在<strong>断电</strong>状态下进行,并确认被测元件无残余电荷。带电测电阻不仅读数错误,还可能损坏万用表。</p></details><p><strong>49.</strong> 使用钳形电流表测量电流时,应( )。</p><ul><li>A. 同时钳入两根导线</li><li>B. 只钳入一根导线</li><li>C. 钳口不闭合</li><li>D. 带电切换量程</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:钳形表靠测量单根导线周围的磁场来测电流,必须<strong>只钳一根导线</strong>。同时钳两根(如火线和零线),磁场相互抵消,读数接近零。</p></details><p><strong>50.</strong> 使用钳形电流表时,切换量程的正确做法是( )。</p><ul><li>A. 直接带电切换</li><li>B. 退出导线后再切换</li><li>C. 快速切换</li><li>D. 任意切换</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:钳形表<strong>不能带电切换量程</strong>,应先把导线退出钳口、或断开电路后再换挡,否则容易产生电弧、损坏仪表。</p></details><p><strong>51.</strong> 兆欧表测量绝缘电阻时,额定转速一般约为( )r/min。</p><ul><li>A. 60</li><li>B. 120</li><li>C. 200</li><li>D. 300</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:手摇兆欧表的额定转速约为 <strong>120r/min</strong>,转速稳定时测量值才准确。转速过低,测得的绝缘电阻会偏小。</p></details><p><strong>52.</strong> 使用兆欧表测量前,应( )。</p><ul><li>A. 直接测量</li><li>B. 切断电源并对被测设备充分放电</li><li>C. 给设备通电</li><li>D. 短接 L、E 端</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:测量前必须<strong>切断电源并充分放电</strong>,尤其是电容、电缆等储能元件。残余电荷会损坏兆欧表,也可能伤人。</p></details><p><strong>53.</strong> 测量电气设备的绝缘电阻应使用( )。</p><ul><li>A. 万用表电阻档</li><li>B. 兆欧表</li><li>C. 钳形电流表</li><li>D. 电能表</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:万用表内部电池电压低,测不出绝缘的真实阻值;绝缘电阻必须使用<strong>兆欧表</strong>(绝缘电阻表),它输出高电压。</p></details><p><strong>54.</strong> 熔断器在电路中主要起( )保护作用。</p><ul><li>A. 过载</li><li>B. 短路</li><li>C. 欠压</li><li>D. 漏电</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:熔断器主要作<strong>短路保护</strong>,短路时熔体迅速熔断切断电路。它也有一定的过载保护能力,但灵敏度不如热继电器。</p></details><p><strong>55.</strong> 热继电器在电路中主要起( )保护作用。</p><ul><li>A. 短路</li><li>B. 过载</li><li>C. 失压</li><li>D. 漏电</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:热继电器利用双金属片受热弯曲动作,主要作电动机的<strong>过载保护</strong>。它有热惯性,短路时来不及动作,不能代替熔断器或断路器。</p></details><p><strong>56.</strong> 交流接触器的主要作用是( )。</p><ul><li>A. 切断短路电流</li><li>B. 频繁接通和断开主电路</li><li>C. 测量电流</li><li>D. 防雷保护</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:交流接触器用于<strong>频繁接通和断开主电路</strong>,可实现远距离控制。它的灭弧能力有限,不能用来切断短路电流。</p></details><p><strong>57.</strong> 交流接触器具有( )保护功能。</p><ul><li>A. 短路</li><li>B. 过载</li><li>C. 失压(欠压)</li><li>D. 漏电</li></ul><details><summary>答案与解析</summary><p><strong>答案:C</strong></p><p>解析:接触器线圈失电即释放,具有<strong>失压(欠压)保护</strong>功能:突然停电后再来电,设备不会自行启动,避免意外。</p></details><p><strong>58.</strong> 低压断路器一般不具有( )功能。</p><ul><li>A. 短路保护</li><li>B. 过载保护</li><li>C. 欠压保护</li><li>D. 防雷保护</li></ul><details><summary>答案与解析</summary><p><strong>答案:D</strong></p><p>解析:低压断路器一般兼具<strong>短路、过载</strong>保护,带欠压脱扣器时还有欠压保护;但<strong>防雷</strong>要靠避雷器等防雷装置,不是断路器的功能。</p></details><h2 id="五、线路、变压器与电动机-第-59-70-题" tabindex="-1">五、线路、变压器与电动机(第 59~70 题) <a class="header-anchor" href="#五、线路、变压器与电动机-第-59-70-题" aria-label="Permalink to &quot;五、线路、变压器与电动机(第 59~70 题)&quot;">​</a></h2><p><strong>59.</strong> 选择导线截面时,不需要考虑的因素是( )。</p><ul><li>A. 发热条件</li><li>B. 电压损失</li><li>C. 机械强度</li><li>D. 导线颜色</li></ul><details><summary>答案与解析</summary><p><strong>答案:D</strong></p><p>解析:导线截面按<strong>发热条件、电压损失、机械强度</strong>选择,大电流线路还要考虑经济电流密度。颜色只用于区分相序和用途,与截面无关。</p></details><p><strong>60.</strong> 一般情况下,铜导线的导电性能比铝导线( )。</p><ul><li>A. 好</li><li>B. 差</li><li>C. 相同</li><li>D. 无法比较</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:铜的电阻率低于铝,导电性能<strong>更好</strong>;同时铜的机械强度和抗氧化性也优于铝。</p></details><p><strong>61.</strong> 导线接头处的接触电阻应( )。</p><ul><li>A. 尽可能小</li><li>B. 尽可能大</li><li>C. 保持原值</li><li>D. 无所谓</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:接头接触电阻增大→局部发热→氧化加剧→电阻更大,形成恶性循环,最终可能烧断或引起火灾。所以接头电阻应<strong>尽可能小</strong>,并做好绝缘恢复。</p></details><p><strong>62.</strong> 变压器的工作原理是( )。</p><ul><li>A. 电磁感应</li><li>B. 光电效应</li><li>C. 热电效应</li><li>D. 压电效应</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:变压器利用一次绕组交变电流产生交变磁通,在二次绕组中感应出电动势,属于<strong>电磁感应</strong>原理。</p></details><p><strong>63.</strong> 变压器( )变换直流电压。</p><ul><li>A. 能</li><li>B. 不能</li><li>C. 降压时能</li><li>D. 升压时能</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:变压器依靠<strong>交变磁通</strong>工作,直流电产生的磁场恒定,二次侧不会感应出电动势,所以<strong>不能</strong>变换直流电压。</p></details><p><strong>64.</strong> 油浸式变压器中,变压器油的主要作用是( )。</p><ul><li>A. 绝缘和冷却</li><li>B. 润滑</li><li>C. 助燃</li><li>D. 导电</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:变压器油既起<strong>绝缘</strong>作用(隔开绕组与铁芯、绕组之间),又通过循环起<strong>冷却散热</strong>作用。它本身可燃,不是助燃剂。</p></details><p><strong>65.</strong> 变压器的变比 K 等于( )。</p><ul><li>A. N1/N2</li><li>B. N2/N1</li><li>C. U2/U1</li><li>D. I2/I1</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:变比 K=<strong>N1/N2=U1/U2</strong>。若 K&gt;1 为降压变压器,K&lt;1 为升压变压器。B、C 都是倒数。</p></details><p><strong>66.</strong> 三相异步电动机的同步转速与( )有关。</p><ul><li>A. 电源频率和磁极对数</li><li>B. 负载大小</li><li>C. 电压高低</li><li>D. 电流大小</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:同步转速 <strong>n1=60f/p</strong>,只与电源频率 f 和磁极对数 p 有关。负载、电压、电流影响的是转差和转矩,不改变同步转速。</p></details><p><strong>67.</strong> 三相异步电动机的转差率一般在( )范围内。</p><ul><li>A. 0</li><li>B. 1%~5%</li><li>C. 10%~20%</li><li>D. 50% 以上</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:正常运行的异步电动机转差率一般在 <strong>1%~5%</strong>(约 2%~5%)。转差率为 0 就是同步电动机,不再是异步电动机。</p></details><p><strong>68.</strong> 三相异步电动机 Y-△ 降压启动适用于( )的电动机。</p><ul><li>A. 任意接法</li><li>B. 正常运行为 △ 接法</li><li>C. 正常运行为 Y 接法</li><li>D. 直流电动机</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:Y-△ 启动是&quot;启动时接成 Y 降压,运行时恢复 △&quot;,所以只适用于<strong>正常运行为 △ 接法</strong>的电动机。记法:&quot;星起角跑&quot;。</p></details><p><strong>69.</strong> 三相异步电动机采用 Y-△ 启动时,启动电流约为直接启动的( )。</p><ul><li>A. 1/2</li><li>B. 1/3</li><li>C. 1/√3</li><li>D. 1/4</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:星形接法时每相电压降为 1/√3,启动电流降为直接启动的 <strong>(1/√3)²=1/3</strong>,启动转矩也降为 1/3。</p></details><p><strong>70.</strong> 改变三相异步电动机转向的方法是( )。</p><ul><li>A. 改变电源电压</li><li>B. 任意对调两相电源线</li><li>C. 改变负载大小</li><li>D. 改变启动方式</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:<strong>任意对调两相电源线</strong>即可改变旋转磁场方向,从而反转。改变电压、负载、启动方式都不能改变转向。</p></details><h2 id="六、配电、照明与防雷接地-第-71-82-题" tabindex="-1">六、配电、照明与防雷接地(第 71~82 题) <a class="header-anchor" href="#六、配电、照明与防雷接地-第-71-82-题" aria-label="Permalink to &quot;六、配电、照明与防雷接地(第 71~82 题)&quot;">​</a></h2><p><strong>71.</strong> 照明开关必须接在( )上。</p><ul><li>A. 零线</li><li>B. 相线</li><li>C. 地线</li><li>D. 任意一线</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:开关必须接在**相线(火线)**上。若接在零线上,关灯后灯头仍然带电,检修或换灯泡时容易触电。记法:&quot;开关控火不控零&quot;。</p></details><p><strong>72.</strong> 螺口灯头的中心触点应接( )。</p><ul><li>A. 零线</li><li>B. 相线</li><li>C. 地线</li><li>D. 任意一线</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:螺口灯头的<strong>中心触点接相线</strong>,螺纹部分接零线。因为螺纹部分容易外露,接零线更安全。</p></details><p><strong>73.</strong> 单相三孔插座正确的接线是( )。</p><ul><li>A. 左火右零上接地</li><li>B. 左零右火上接地</li><li>C. 左零右火下接地</li><li>D. 上零下火</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:面对插座看,<strong>左零、右火、上接地</strong>。这是国标统一规定,便于检查和维修。</p></details><p><strong>74.</strong> 三相五线制中,PE 线的颜色是( )。</p><ul><li>A. 淡蓝色</li><li>B. 黄绿双色</li><li>C. 红色</li><li>D. 黑色</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:PE(保护线)采用<strong>黄绿双色</strong>线,这是专用色,不得挪作他用;N 线用淡蓝色。</p></details><p><strong>75.</strong> 三相电源 L1、L2、L3 相线的颜色依次为( )。</p><ul><li>A. 黄、绿、红</li><li>B. 红、黄、绿</li><li>C. 绿、红、黄</li><li>D. 蓝、黄、绿</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:相线颜色依次为 <strong>L1 黄、L2 绿、L3 红</strong>;N 线淡蓝,PE 线黄绿双色。记法:&quot;黄绿红&quot;。</p></details><p><strong>76.</strong> 避雷针的主要作用是( )。</p><ul><li>A. 阻止雷云形成</li><li>B. 将雷电流引入大地</li><li>C. 储存雷电能量</li><li>D. 中和雷云电荷</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:避雷针是&quot;引雷&quot;而不是&quot;消雷&quot;,它把雷电流<strong>引入大地</strong>,保护其保护范围内的设备和建筑物。</p></details><p><strong>77.</strong> 独立避雷针的接地电阻一般不应大于( )Ω。</p><ul><li>A. 4</li><li>B. 10</li><li>C. 30</li><li>D. 100</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:独立避雷针的接地电阻一般要求 <strong>≤10Ω</strong>,以保证雷电流迅速泄放入地,降低反击电压。</p></details><p><strong>78.</strong> 防雷装置一般由( )组成。</p><ul><li>A. 接闪器、引下线、接地装置</li><li>B. 熔断器、断路器、接触器</li><li>C. 避雷器、电容器、电抗器</li><li>D. 导线、开关、插座</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:防雷装置由**接闪器(接雷)、引下线(导雷)、接地装置(泄雷)**三部分组成,缺一不可。</p></details><p><strong>79.</strong> 电能表是用来测量( )的仪表。</p><ul><li>A. 电功率</li><li>B. 电能</li><li>C. 电流</li><li>D. 电压</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:电能表(电度表)测量的是<strong>电能</strong>,单位是 kW·h;电功率的单位是 kW,两者不同。</p></details><p><strong>80.</strong> 电能表铭牌&quot;220V 10(40)A&quot;中,40A 表示( )。</p><ul><li>A. 基本电流</li><li>B. 额定最大电流</li><li>C. 启动电流</li><li>D. 短路电流</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:括号外的 10A 是<strong>基本电流</strong>,括号内的 40A 是<strong>额定最大电流</strong>。括号里的是允许长期运行的上限。</p></details><p><strong>81.</strong> TN-S 系统中,N 线与 PE 线的关系是( )。</p><ul><li>A. 合并为一根</li><li>B. 分开敷设</li><li>C. 可随意合并</li><li>D. 都不接地</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:TN-S 中的 S 表示 Separate,即 N 线与 PE 线<strong>全程分开</strong>,这就是三相五线制。合并的是 TN-C。</p></details><p><strong>82.</strong> TN-C 系统中,PEN 线的作用是( )。</p><ul><li>A. 只作相线</li><li>B. 兼作中性线和保护线</li><li>C. 只作接地极</li><li>D. 只作控制线</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:TN-C 中的 C 表示 Combined,<strong>PEN 线兼作中性线(N)和保护线(PE)</strong>,即三相四线制。它不能用作相线。</p></details><h2 id="七、防火防爆、触电急救与作业规范-第-83-100-题" tabindex="-1">七、防火防爆、触电急救与作业规范(第 83~100 题) <a class="header-anchor" href="#七、防火防爆、触电急救与作业规范-第-83-100-题" aria-label="Permalink to &quot;七、防火防爆、触电急救与作业规范(第 83~100 题)&quot;">​</a></h2><p><strong>83.</strong> 电气火灾发生后,首先应( )。</p><ul><li>A. 用水灭火</li><li>B. 切断电源</li><li>C. 打开门窗通风</li><li>D. 立即撤离现场</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:电气火灾应<strong>先切断电源</strong>再灭火。带电灭火有触电危险,而且水流、泡沫都导电。</p></details><p><strong>84.</strong> 带电灭火时,应选用( )灭火器。</p><ul><li>A. 泡沫灭火器</li><li>B. 水基型灭火器</li><li>C. 干粉或二氧化碳灭火器</li><li>D. 酸碱灭火器</li></ul><details><summary>答案与解析</summary><p><strong>答案:C</strong></p><p>解析:<strong>干粉和二氧化碳</strong>灭火剂不导电,可用于带电灭火;泡沫、水基、酸碱灭火剂都导电,禁止带电使用。</p></details><p><strong>85.</strong> 泡沫灭火器( )用于带电灭火。</p><ul><li>A. 可以</li><li>B. 不能</li><li>C. 降压后可以</li><li>D. 小电流时可以</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:泡沫灭火剂含水分、导电,会形成导电通路,<strong>不能</strong>用于带电灭火。带电灭火只能选干粉或二氧化碳。</p></details><p><strong>86.</strong> 发现有人触电,首先应( )。</p><ul><li>A. 直接用手拉开触电者</li><li>B. 迅速切断电源或用绝缘物使其脱离电源</li><li>C. 先打电话</li><li>D. 先泼水降温</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:第一步必须是<strong>使触电者脱离电源</strong>:拉闸断电,或用干燥木棒、绝缘工具挑开电线。直接用手拉会导致救人者一起触电。</p></details><p><strong>87.</strong> 成人心肺复苏时,胸外按压与人工呼吸的比例为( )。</p><ul><li>A. 15:2</li><li>B. 30:2</li><li>C. 5:1</li><li>D. 15:1</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:现行成人心肺复苏标准为<strong>每按压 30 次、吹气 2 次</strong>,即 30:2。15:2 是旧标准或双人婴幼儿复苏的比例,不要混。</p></details><p><strong>88.</strong> 成人心肺复苏时,胸外按压的深度约为( )cm。</p><ul><li>A. 1~2</li><li>B. 5~6</li><li>C. 8~10</li><li>D. 10~12</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:成人胸外按压深度为 <strong>5~6cm</strong>。太浅形成不了有效循环,太深容易造成肋骨骨折和内脏损伤。</p></details><p><strong>89.</strong> 成人心肺复苏时,胸外按压的频率为每分钟( )次。</p><ul><li>A. 40~60</li><li>B. 60~80</li><li>C. 100~120</li><li>D. 140~160</li></ul><details><summary>答案与解析</summary><p><strong>答案:C</strong></p><p>解析:按压频率应为 <strong>100~120 次/分</strong>。过快会影响心脏回血,过慢则循环不足。</p></details><p><strong>90.</strong> 停电检修作业的正确顺序是( )。</p><ul><li>A. 验电→停电→接地→挂标示牌</li><li>B. 停电→验电→装设接地线→悬挂标示牌</li><li>C. 挂标示牌→停电→验电</li><li>D. 接地→停电→验电</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:正确顺序是<strong>停电 → 验电 → 装设接地线 → 悬挂标示牌和装设遮栏</strong>。不停电无法验电,不验电不能确认无电,顺序不能颠倒。</p></details><p><strong>91.</strong> 装设接地线时,正确的顺序是( )。</p><ul><li>A. 先接导体端,后接接地端</li><li>B. 先接接地端,后接导体端</li><li>C. 两端同时连接</li><li>D. 顺序无所谓</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:必须先接<strong>接地端</strong>、后接<strong>导体端</strong>,这样即使导线意外带电,电流也会直接入地,不会通过人体。拆除时顺序相反。</p></details><p><strong>92.</strong> 验电时应使用( )的验电器。</p><ul><li>A. 电压等级相符</li><li>B. 任意电压等级</li><li>C. 高压验电器验低压</li><li>D. 低压验电器验高压</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:必须使用<strong>电压等级相符</strong>的验电器。低压验电器验高压会击穿伤人,高压验电器验低压则可能不亮,造成误判。</p></details><p><strong>93.</strong> 在低压电气设备上工作,一般应办理( )。</p><ul><li>A. 工作票或工作许可手续</li><li>B. 口头通知即可</li><li>C. 无需任何手续</li><li>D. 请假手续</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:电气作业应办理<strong>工作票或工作许可手续</strong>,落实安全措施、明确工作范围和责任人。口头通知不能替代。</p></details><p><strong>94.</strong> 安全标识中,红色表示( )。</p><ul><li>A. 禁止、停止</li><li>B. 警告</li><li>C. 指令</li><li>D. 提示</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:安全色中,<strong>红色表示禁止、停止</strong>(如&quot;禁止合闸,有人工作&quot;);黄色表示警告,蓝色表示指令,绿色表示提示。</p></details><p><strong>95.</strong> 安全标识中,黄色表示( )。</p><ul><li>A. 禁止</li><li>B. 警告</li><li>C. 指令</li><li>D. 提示</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:<strong>黄色表示警告</strong>(如&quot;当心触电&quot;&quot;注意安全&quot;)。红禁、黄警、蓝指令、绿提示。</p></details><p><strong>96.</strong> 安全标识中,绿色表示( )。</p><ul><li>A. 禁止</li><li>B. 警告</li><li>C. 指令</li><li>D. 提示、安全状态</li></ul><details><summary>答案与解析</summary><p><strong>答案:D</strong></p><p>解析:<strong>绿色表示提示和安全状态</strong>(如&quot;在此工作&quot;&quot;已接地&quot;),也用于安全通道、急救点等标识。</p></details><p><strong>97.</strong> 安全标识中,蓝色表示( )。</p><ul><li>A. 禁止</li><li>B. 警告</li><li>C. 指令</li><li>D. 提示</li></ul><details><summary>答案与解析</summary><p><strong>答案:C</strong></p><p>解析:<strong>蓝色表示指令</strong>,要求必须遵守,如&quot;必须戴安全帽&quot;&quot;必须穿绝缘鞋&quot;。</p></details><p><strong>98.</strong> 在爆炸危险场所,应使用( )电气设备。</p><ul><li>A. 普通型</li><li>B. 防爆型</li><li>C. 任意型</li><li>D. 防水型</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:爆炸危险场所必须使用<strong>防爆型</strong>电气设备,防止电火花或高温引燃爆炸性混合物。普通型、防水型都不满足防爆要求。</p></details><p><strong>99.</strong> 从业人员在作业过程中,应当正确佩戴和使用( )。</p><ul><li>A. 劳动防护用品</li><li>B. 装饰品</li><li>C. 手机</li><li>D. 娱乐设备</li></ul><details><summary>答案与解析</summary><p><strong>答案:A</strong></p><p>解析:从业人员有义务<strong>正确佩戴和使用劳动防护用品</strong>,这是保护自身安全的最后一道防线,不能以&quot;不方便&quot;为由不戴。</p></details><p><strong>100.</strong> 发生电气火灾且无法切断电源时,应( )。</p><ul><li>A. 用水扑救</li><li>B. 使用不导电的灭火剂并保持安全距离</li><li>C. 用泡沫扑救</li><li>D. 等待电源自动断开</li></ul><details><summary>答案与解析</summary><p><strong>答案:B</strong></p><p>解析:无法断电时应使用<strong>干粉、二氧化碳等不导电灭火剂</strong>,并保持足够的安全距离,防止触电和电弧伤人。绝不能用水或泡沫。</p></details>',310)])])}const y=i(o,[["render",n]]);export{d as __pageData,y as default};
